{"code":"import pandas as pd
import ast

# The user's code provided in the prompt
def processing(dfs):
    df = dfs[0]
    if df.empty:
        return pd.DataFrame({'succeeded_visa_payments': [0]})

    count = 0
    for p_str in df['payload']:
        # This cleaning might actually break for valid JSON!
        # JSON uses double quotes, so if you replace 'true' with 'True', etc., 
        # that's fine. But what if it's already a valid JSON string?
        # The user's cleaning logic:
        # p_str.replace('null', 'None').replace('true', 'True').replace('false', 'False')                
        # This doesn't replace double quotes.
        # So 'null' becomes 'None' ... but 'null' was not necessarily in it...

        # Let's just run their code as given on the data.
        clean_str = p_str.replace('null', 'None').replace('true', 'True').replace('false', 'False')
        try:
            payload = ast.literal_eval(clean_str)
        except:
            # Skip rows where the JSON parsing fails
            continue

        is_succeeded = False
        is_visa = False
        obj_type = payload.get('object')
        if obj_type == 'payment_intent':
            if str(payload.get('state', '')).lower() == 'succeeded':
                is_succeeded = True
            pm = payload.get('payment_method')
            if pm and isinstance(pm, dict):
                if pm.get('type') == 'card':
                    card_info = pm.get('card', {})
                    if str(card_info.get('network', '')).lower() == 'visa':
                        is_visa = True
        elif obj_type == 'charge':
            if str(payload.get('status', '')).lower() == 'succeeded':
                is_succeeded = True
            card_info = payload.get('card')
            if card_info and isinstance(card_info, dict):
                if str(card_info.get('brand', '')).lower() == 'visa':
                    is_visa = True
        if is_succeeded and is_visa:
            count += 1

    return pd.DataFrame({'succeeded_visa_payments': [count]})

df = pd.DataFrame(conn.execute("SELECT payload FROM payment_events").fetchall(), columns=['payload'])
result = processing([df])
print(result)
"}

