{"code":"import json
import pandas as pd

# Fetch all payloads
payloads = conn.execute("SELECT payload FROM payment_events").fetchall()

# Count distinct payment_method.type
pm_types = set()
for p_tuple in payloads:
    p_str = p_tuple[0]
    try:
        payload = json.loads(p_str)
        if payload.get('object') == 'payment_intent':
            pm = payload.get('payment_method')
            if pm:
                pm_types.add(pm.get('type'))
    except:
        continue
print(f"Payment method types: {pm_types}")
