{"code":"import json
import ast
import pandas as pd

def parse_payload(payload_str):
    try:
        return json.loads(payload_str)
    except:
        return ast.literal_eval(payload_str)

def processing(dfs):
    df = dfs[0]
    count = 0
    for payload_str in df['payload']:
        try:
            data = parse_payload(payload_str)
            obj = data.get('object', '')
            status = None
            brand = None

            # Existing logic for charge/payment_intent
            if obj == 'charge':
                status = data.get('status')
                brand = data.get('card', {}).get('brand')
            elif obj == 'payment_intent':
                status = data.get('state')
                brand = data.get('payment_method', {}).get('card', {}).get('network')

            # Fallback for wallet or other objects as per plan
            if status is None:
                status = data.get('transaction', {}).get('result', {}).get('status')
            if brand is None:
                brand = data.get('instrument', {}).get('details', {}).get('card_brand')

            # Check for matches (case-insensitive)
            if status and isinstance(status, str) and brand and isinstance(brand, str):
                if status.lower() == 'succeeded' and brand.lower() == 'visa':
                    count += 1
        except Exception:
            continue
    return pd.DataFrame({'succeeded_visa_payments_count': [count]})

# Run with full data
# The interpreter will have the connection 'conn' and the DataFrame
# Let me load the data first so I can test the processing function with it
df = pd.read_sql_query("SELECT payload FROM payment_events", conn)
print(processing([df]))
"}

